  -- CoefAddr
  CoefAddr_process : PROCESS (clk, aresetn)
  BEGIN
    IF aresetn = '0' THEN
      CoefAddr_cnt <= to_unsigned(16#0#, 3);
      CoefAddr_state <= '0';
    ELSIF clk'EVENT AND clk = '1' THEN
      CoefAddr_cnt <= CoefAddr_cnt_next;
      CoefAddr_state <= CoefAddr_state_next;
    END IF;
  END PROCESS CoefAddr_process;

  CoefAddr_output : PROCESS (CoefAddr_cnt, CoefAddr_state, validIn)
  BEGIN
    CoefAddr_cnt_next <= CoefAddr_cnt;
    CoefAddr_1 <= CoefAddr_cnt;
    IF CoefAddr_state = '0' THEN 
      CoefAddr_state_next <= '0';
      CoefAddr_cnt_next <= to_unsigned(16#0#, 3);
      IF validIn = '1' THEN 
        CoefAddr_state_next <= '1';
      END IF;
    ELSE 
      CoefAddr_state_next <= '1';
      IF validIn = '1' THEN 
        IF CoefAddr_cnt = to_unsigned(16#4#, 3) THEN 
          CoefAddr_cnt_next <= to_unsigned(16#0#, 3);
        ELSE 
          CoefAddr_cnt_next <= CoefAddr_cnt + to_unsigned(16#1#, 3);
        END IF;
      END IF;
    END IF;
  END PROCESS CoefAddr_output;


